class GpsFormController{constructor($scope,$timeout,$mdDialog,DispatchData,toastrService,rateJobService,NgMap,currentJob,addressDetails,field,suburbOptions){this.$scope=$scope;this.$timeout=$timeout;this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService;this.rateJobService=rateJobService;this.NgMap=NgMap;this.currentJob=currentJob;this.addressDetails=addressDetails;this.field=field;this.suburbOptions=suburbOptions;this.title="Update Address and GPS";this.addressDetails=addressDetails;this.ourSuburbSearchText="";this.addressSearchText="";this.ourSuburbSelectedItem=this.findSuburbByDistrict(addressDetails.suburb);$timeout(()=>{this.mapDisplay=true},500);NgMap.getMap().then(map=>{console.log("Loading Map!");this.map=map;this.marker=map.markers[0];this.addressSearchAutocomplete(addressDetails.address).then(_=>console.log("Address Search Complete!"))})}findSuburbByDistrict(district){let lowerCaseDistrict=district.toLowerCase();return this.suburbOptions.find(localSuburb=>localSuburb.text.toLowerCase()===lowerCaseDistrict||localSuburb.alias&&localSuburb.alias.toLowerCase()===lowerCaseDistrict)}transformSuggestions(data){return data.suggestions.map(obj=>({id:obj.locationId,text:obj.label.split(", ").reverse().join(", ")}))}ourSuburbSearch(query){return query?this.suburbOptions.filter(suburb=>suburb.text.toLowerCase().indexOf(query.toLowerCase())!==-1):this.suburbOptions}async addressSearchAutocomplete(searchText){try{const suggestions=await this.DispatchData.autocompleteAddressSearch(searchText);return this.transformSuggestions(suggestions)}catch(error){this.toastrService.showErrorToast(error.message)}}async addressSearchItemSelected(item){try{const data=await this.DispatchData.getGeoCodeInformation(item);const returnedLocation=data.Response.View[0].Result[0].Location;console.log("Suburb = "+returnedLocation.Address.District);console.log("PostCode = "+returnedLocation.Address.PostalCode);const mappedSub=this.findSuburbByDistrict(returnedLocation.Address.District);if(mappedSub!==undefined){console.log(mappedSub);this.ourSuburbSelectedItem=mappedSub}else{this.ourSuburbSelectedItem=null;this.toastrService.showWarningToast("Matching suburb could not be found from this address."+"Please select manually.")}this.addressDetails.filledAddress=returnedLocation.Address.Label;this.addressDetails.lat=returnedLocation.DisplayPosition.Latitude;this.addressDetails.long=returnedLocation.DisplayPosition.Longitude;this.addressDetails.address=returnedLocation.Address.Label;this.addressDetails.suburb=returnedLocation.Address.District;this.addressDetails.postCode=returnedLocation.Address.PostalCode;const latLng=new google.maps.LatLng(returnedLocation.DisplayPosition.Latitude,returnedLocation.DisplayPosition.Longitude);this.map.setCenter(latLng);this.marker.setPosition(latLng)}catch(error){console.log("Error: ",error)}}async submit(addressDetails){try{const job=this.currentJob;if(this.ourSuburbSelectedItem.id!==undefined){addressDetails.our_suburb=this.ourSuburbSelectedItem.id}if(addressDetails.our_suburb===undefined){const alert=this.$mdDialog.alert({title:"Courier Suburb Not Mapped",textContent:"You must pick one of our suburbs to map this address to",ok:"Close"});await this.$mdDialog.show(alert)}if(this.field==="toAddress"){job.toAddress=(addressDetails.extras||"").length>1?addressDetails.extras+","+addressDetails.address:addressDetails.address;if(job.bulkJob){await this.DispatchData.updateBulkDeliveryAddress(job.id,addressDetails.suburb,addressDetails.postCode,job.toAddress,addressDetails.lat,addressDetails.long,FirstName);this.$mdDialog.hide();this.toastrService.showSuccessToast("Address successfully updated")}job.toSuburbID=parseInt(addressDetails.our_suburb)}else{job.fromAddress=(addressDetails.extras||"").length>1?addressDetails.extras+","+addressDetails.address:addressDetails.address;if(job.bulkJob){await this.DispatchData.updateBulkPickupAddress(job.id,addressDetails.suburb,addressDetails.postCode,job.fromAddress,addressDetails.lat,addressDetails.long,FirstName);this.$mdDialog.hide();this.toastrService.showSuccessToast("Address successfully updated")}job.fromSuburbID=parseInt(addressDetails.our_suburb)}const pedal=job.fromSuburbID===1&&job.toSuburbID===1||job.fromSuburbID===112&&job.toSuburbID===112||job.fromSuburbID===480&&job.toSuburbID===480;const rate=await this.rateJobService.rateJob(job);const callData={call:"updateJobData",addressField:this.field,lat:addressDetails.lat,long:addressDetails.long,fromSuburbId:job.fromSuburbID,toSuburbId:job.toSuburbID,fromAddress:job.fromAddress,toAddress:job.toAddress,rate:rate,jobID:job.id,CBD:pedal};console.log(callData);if(this.field==="toAddress"){await this.DispatchData.updateDeliveryAddress(callData.jobID,callData.toSuburbId,callData.toAddress,callData.lat,callData.long,callData.CBD,Number(callData.rate.replace(/[^0-9.-]+/g,"")),FirstName,job.preBook);this.$mdDialog.hide();this.toastrService.showSuccessToast("Address successfully updated")}else{await this.DispatchData.updatePickupAddress(callData.jobID,callData.fromSuburbId,callData.fromAddress,callData.lat,callData.long,callData.CBD,Number(callData.rate.replace(/[^0-9.-]+/g,"")),FirstName,job.preBook);this.$mdDialog.hide();this.toastrService.showSuccessToast("Address successfully updated")}}catch(error){this.toastrService.showErrorToast(error.message)}}copyGpsAddress(address){this.addressSearchText=address}moveMarker(event){this.addressDetails.lat=event.latLng.lat();this.addressDetails.long=event.latLng.lng();this.$scope.$apply()}markerDragend(event){const location=event.latLng;try{this.DispatchData.retrieveAddresses(location.lat(),location.lng()).then(data=>{const returnedLocation=data.Response.View[0].Result[0].Location;this.addressDetails.address=returnedLocation.Address.Label;this.addressDetails.suburb=returnedLocation.Address.District;this.addressDetails.lat=returnedLocation.DisplayPosition.Latitude;this.addressDetails.long=returnedLocation.DisplayPosition.Longitude;console.log("Suburb = "+returnedLocation.Address.District);console.log("PostCode = "+returnedLocation.Address.PostalCode);const mappedSub=this.suburbOptions.find(obj=>obj.text===returnedLocation.Address.District||obj.alias===returnedLocation.Address.District);if(mappedSub!==undefined){console.log(mappedSub);this.ourSuburbSelectedItem=mappedSub}else{this.ourSuburbSelectedItem=null}})}catch(error){this.toastrService.showErrorToast(error.message)}}placeChanged(place){try{this.addressDetails.lat=place.geometry.location.lat();this.addressDetails.long=place.geometry.location.lng();if(place.address_components.find(x=>x.types[0]==="postal_code")){this.addressDetails.postCode=place.address_components.find(x=>x.types[0]==="postal_code").long_name}this.map.setCenter(place.geometry.location)}catch(error){this.toastrService.showErrorToast(error.message)}}cancel(){this.$mdDialog.cancel()}}